import {
  base32Decode,
  base32Encode,
  concatBytes,
  timingSafeEqual,
  utf8Decode,
  utf8Encode,
} from "@/lib/encoding";
import type { TrackTarget } from "@/lib/payload/qr-types";

/**
 * Tracked links are self-contained and signed:
 *
 *   https://<link-base>/r/<TOKEN>
 *   TOKEN = base32( header | nonce(6) | body | mac(8) )
 *
 *   header  = version(2 bits) | keyId(3 bits) | kind(3 bits)
 *   nonce   = random, generated by the server; its base32 form is the count ID
 *   body    = destination (UTF-8), with a common prefix replaced by `kind`
 *   mac     = HMAC-SHA256(secret[keyId], header|nonce|body), first 8 bytes
 *
 * The destination lives inside the link, so nothing about it is stored on the
 * server; only an anonymous counter keyed by the nonce. The MAC stops anyone
 * from minting links that redirect elsewhere through our domain. 64 bits is
 * ample for an online-only check (each guess costs an HTTP request).
 */

export const TOKEN_VERSION = 0;
export const NONCE_BYTES = 6;
export const MAC_BYTES = 8;

const PREFIXES = ["", "https://", "https://www.", "http://", "http://www."] as const;
const KIND_APP = 5;

export const COUNT_ID_RE = /^[A-Z2-7]{10}$/;

export interface ParsedToken {
  version: number;
  keyId: number;
  kind: number;
  nonce: Uint8Array;
  body: Uint8Array;
  mac: Uint8Array;
  /** The bytes covered by the MAC. */
  signed: Uint8Array;
  countId: string;
}

export function parseToken(token: string): ParsedToken | null {
  if (!/^[A-Za-z2-7]{20,2000}$/.test(token)) return null;
  const bytes = base32Decode(token);
  if (!bytes || bytes.length < 1 + NONCE_BYTES + 1 + MAC_BYTES) return null;
  const header = bytes[0];
  const version = header >> 6;
  if (version !== TOKEN_VERSION) return null;
  const nonce = bytes.slice(1, 1 + NONCE_BYTES);
  return {
    version,
    keyId: (header >> 3) & 7,
    kind: header & 7,
    nonce,
    body: bytes.slice(1 + NONCE_BYTES, bytes.length - MAC_BYTES),
    mac: bytes.slice(bytes.length - MAC_BYTES),
    signed: bytes.slice(0, bytes.length - MAC_BYTES),
    countId: base32Encode(nonce),
  };
}

/** Extracts the count ID from a tracked link or bare token without verifying it. */
export function countIdFromLink(link: string): string | null {
  const m = /\/r\/([A-Za-z2-7]+)\/?(?:[?#].*)?$/.exec(link.trim());
  const parsed = parseToken(m ? m[1] : link.trim());
  return parsed ? parsed.countId : null;
}

function packTarget(target: TrackTarget): { kind: number; body: Uint8Array } {
  if (target.kind === "app") {
    return { kind: KIND_APP, body: utf8Encode([target.ios, target.android, target.fallback].join("\n")) };
  }
  let kind = 0;
  for (let i = 1; i < PREFIXES.length; i++) {
    if (target.url.startsWith(PREFIXES[i]) && PREFIXES[i].length > PREFIXES[kind].length) kind = i;
  }
  return { kind, body: utf8Encode(target.url.slice(PREFIXES[kind].length)) };
}

export function unpackTarget(kind: number, body: Uint8Array): TrackTarget | null {
  let text: string;
  try {
    text = utf8Decode(body);
  } catch {
    return null;
  }
  if (kind === KIND_APP) {
    const [ios = "", android = "", fallback = ""] = text.split("\n");
    return { kind: "app", ios, android, fallback };
  }
  if (kind >= PREFIXES.length) return null;
  return { kind: "url", url: PREFIXES[kind] + text };
}

async function hmac(key: CryptoKey, data: Uint8Array): Promise<Uint8Array> {
  const sig = await crypto.subtle.sign("HMAC", key, data as BufferSource);
  return new Uint8Array(sig).slice(0, MAC_BYTES);
}

export function importSecret(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    "raw",
    utf8Encode(secret) as BufferSource,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
}

export async function signToken(
  target: TrackTarget,
  key: CryptoKey,
  keyId: number,
  nonce: Uint8Array,
): Promise<{ token: string; countId: string }> {
  if (nonce.length !== NONCE_BYTES) throw new Error("Bad nonce length");
  const { kind, body } = packTarget(target);
  const header = new Uint8Array([(TOKEN_VERSION << 6) | ((keyId & 7) << 3) | kind]);
  const signed = concatBytes(header, nonce, body);
  const mac = await hmac(key, signed);
  return { token: base32Encode(concatBytes(signed, mac)), countId: base32Encode(nonce) };
}

export async function verifyToken(parsed: ParsedToken, key: CryptoKey): Promise<boolean> {
  return timingSafeEqual(await hmac(key, parsed.signed), parsed.mac);
}
